1	import type {
2	  IsoTimestamp,
3	  MemberId,
4	  OrgId,
5	  SoftDeletable,
6	  TenantScoped,
7	  Timestamps,
8	  UserId,
9	  InvitationId,
10	} from "./common";
11	
12	/**
13	 * Taskflow RBAC roles, ordered from most to least privileged. `ROLE_RANK`
14	 * below is the single source of truth for "at least this role" comparisons —
15	 * never compare role strings directly.
16	 */
17	export type Role = "owner" | "admin" | "member" | "viewer";
18	
19	export const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];
20	
21	export const ROLE_RANK: Readonly<Record<Role, number>> = {
22	  owner: 4,
23	  admin: 3,
24	  member: 2,
25	  viewer: 1,
26	};
27	
28	export type MemberStatus = "active" | "invited" | "suspended";
29	
30	export interface User extends Timestamps {
31	  readonly id: UserId;
32	  readonly email: string;
33	  readonly name: string;
34	  readonly avatarUrl: string | null;
